function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(str).replace(/[&<>"']/g, (ch) => map[ch]);
}

const cases = [
  ['<script>alert(1)</script>', '&lt;script&gt;alert(1)&lt;/script&gt;'],
  ['a & b < c', 'a &amp; b &lt; c'],
  ['"quoted"', '&quot;quoted&quot;'],
  ["it's a test", 'it&#39;s a test'],
  [123, '123'],
  [null, ''],
  ['普通中文 no change', '普通中文 no change']
];
let pass = 0;
for (const [input, expected] of cases) {
  const got = escapeHtml(input);
  const ok = got === expected;
  if (ok) pass++;
  console.log(ok ? 'PASS' : 'FAIL', JSON.stringify(input), '->', got);
}
console.log(`通过 ${pass}/${cases.length}`);

const crypto = require('node:crypto');

// 同步令牌模式：token 与服务端 session 绑定，校验通过即作废（一次性）
class CsrfTokenStore {
  constructor() {
    this.sessionToken = new Map(); // sessionId -> token
  }

  generate(sessionId) {
    const token = crypto.randomBytes(32).toString('hex');
    this.sessionToken.set(sessionId, token);
    return token;
  }

  // 恒定时间比较，避免计时侧信道
  safeEqual(a, b) {
    const ba = Buffer.from(a || '');
    const bb = Buffer.from(b || '');
    if (ba.length !== bb.length) return false;
    return crypto.timingSafeEqual(ba, bb);
  }

  validate(sessionId, token) {
    if (typeof token !== 'string' || token.length === 0) return false;
    const expected = this.sessionToken.get(sessionId);
    if (!expected || !this.safeEqual(token, expected)) return false;
    this.sessionToken.delete(sessionId); // 一次性，防重放
    return true;
  }
}

const store = new CsrfTokenStore();
const t1 = store.generate('sess-1');
console.log('token 长度(hex):', t1.length); // 64
console.log('伪造 token 校验:', store.validate('sess-1', 'a'.repeat(64))); // false
console.log('正确 token 校验:', store.validate('sess-1', t1)); // true
console.log('同一 token 重放:', store.validate('sess-1', t1)); // false

const t2 = store.generate('sess-1');
console.log('拿 sess-1 的 token 冒充 sess-2:', store.validate('sess-2', t2)); // false
console.log('sess-1 本人正确校验:', store.validate('sess-1', t2)); // true
